feedPosts.push(...[{"id": "mzday26p01", "day": 26, "author": "종이수집가", "time": "08:37", "text": "접착제 묻은 손으로 엽서 넘기다가 두 장 붙여 버림 이걸 떼면 찢어질 것 같은데 이제 그냥 한 장으로 치면 안 되나", "comments": [["관성", "두 장 가격인 건 변함없는데"], ["종이수집가", "너 왜 그걸 지금 말해"], ["뿌꾸", "뭔가 새 장르의 엽서다"]]}, {"id": "mzday26p02", "day": 26, "author": "zZ", "time": "10:18", "text": "일어나자마자 오늘 하루치 피곤함을 다 느낌", "comments": [["개굴", "다시 누워"], ["zZ", "이미 세수했어"], ["나사한통", "되돌릴 수 없는 일 저질렀네"]]}, {"id": "mzday26p03", "day": 26, "author": "관문골목", "time": "12:04", "text": "주말 지나고 나니까 관문 앞에서 사진 찍는 사람 좀 늘어난 것 같음 여기서 뭐 볼 게 그렇게 많지", "comments": [["지도가있어도길치", "며칠 전에 올라온 먹방 영상 보고 오는 사람들도 있을걸"], ["관문골목", "아 그거 때문인가"], ["동네산책", "요즘 골목 사진 진짜 많이 보이긴 하더라"]]}, {"id": "mzday26p04", "day": 26, "author": "오늘은제가먼저내립니다", "time": "14:22", "text": "셔틀에서 내릴 때 뒤에 아무도 없는데 문 잡고 서 있었음 누가 먼저 지나가겠지 하고 3초 기다림 아무도 없었음", "comments": [["종점에서내려요", "친절이 공중에 흩날렸네요"], ["오늘은제가먼저내립니다", "제발 좀 가져가 주세요"]]}, {"id": "mzday26p05", "day": 26, "author": "나사한통", "time": "16:01", "text": "공구함 정리할 때마다 빠지는 게 하나씩 생김 오늘은 잠금쇠를 어디다 뒀더라", "comments": [["초록장갑", "아니 그정도면 너 정리하면 안돼는거 아니냐"], ["마춤뻡검사기", "안돼 > 안되"], ["개굴", "잠금쇠 없으면 공구함 입장에선 자유지"]]}, {"id": "mzday26p06", "day": 26, "author": "부릉부릉", "time": "17:13", "text": "식사하다가 옆자리 사람이 주문한 게 너무 맛있어 보였음 이미 내 메뉴 나왔는데 후회됨", "comments": [["동네산책", "한 입 달라고 해"], ["부릉부릉", "모르는 사람임;;"], ["개굴", "그럼 두 개 먹어"], ["부릉부릉", "그만 부추겨"]]}]);

feedPosts.push(...[{"id": "mzday27p01", "day": 27, "author": "종이수집가", "time": "08:12", "text": "예전에 사 둔 메모지가 드디어 바닥남 마지막 장에 '메모지 사기'라고 쓰려다가 자리가 없었음", "comments": [["관성", "외워"], ["종이수집가", "그게 됐으면 메모지를 왜 샀겠어"]]}, {"id": "mzday27p02", "day": 27, "author": "헙", "time": "09:34", "text": "아침에 일어나자마자 어제 먹은 게 생각남 아직 소화도 안 됐는데", "comments": [["개굴", "좋은 하루의 시작이네"], ["헙", "내 위장은 그렇게 생각 안 하는 듯"]]}, {"id": "mzday27p03", "day": 27, "author": "초록장갑", "time": "11:08", "text": "오늘 동료가 음료에 뭐 올릴지로 10분 동안 고민함 그러더니 결국 사진만 찍고 아무것도 안 시킴", "comments": [["나사한통", "가게 앞에서?"], ["초록장갑", "아니 쉬는 시간에 단말기로 메뉴 사진 보면서"], ["나사한통", "아 그럼 인정"]]}, {"id": "mzday27p04", "day": 27, "author": "내일은일찍들어가야지", "time": "13:47", "text": "이번 주에 친구들이랑 약속 잡음 장소는 정했는데 회사가 몇시에 끝날지는 아무도 모름ㅎ...", "comments": [["부릉부릉", "만약 야근 잡히면 어쩌려고"], ["내일은일찍들어가야지", "일해야지 그럼..."]]}, {"id": "mzday27p05", "day": 27, "author": "관성", "time": "15:26", "text": "다들 뭔가 유행한다길래 찾아봤는데 이게 왜 유행인지 알아보는 동안 다른 게 유행하기 시작함", "comments": [["지도가있어도길치", "유행을 공부하려고 해서 그래"], ["개굴", "늑킄크"], ["관성", "뭣"]]}, {"id": "mzday27p06", "day": 27, "author": "부릉부릉", "time": "17:18", "text": "관문 쪽 먹방 영상 또 돌려봄 아는 길이 영상에 나오니까 괜히 반가움", "comments": [["냐카웃", "나도 처음엔 장소가 어딘지 몰랐음"], ["부릉부릉", "알고 나니까 저 간판이 왜 이제야 보이나 싶어"]]}] );

feedPosts.push(...[{"id": "mzday28p01", "day": 28, "author": "종이수집가", "time": "08:16", "text": "새 수첩 첫 장에 오늘 할 일 적었음 근데 할 일을 다 하고 나니까 수첩을 어디 뒀는지 모르겠음", "comments": [["관성", "할 일을 하나 더 만들었네"], ["종이수집가", "찾기 전엔 완료 표시도 못 해"], ["개굴", "다음엔 수첩에 수첩 찾기 적어"], ["종이수집가", "그 수첩이 없다고"]]}, {"id": "mzday28p02", "day": 28, "author": "0_o", "time": "09:42", "text": "이어폰 한쪽만 끼고 나왔는데 정작 음악은 안 틀고 두 시간 돌아다님", "comments": [["나사한통", "주변 소리 들으려고 그런 거 아니야?"], ["0_o", "그럴 거면 귀는 왜 막았냐고 나한테 물어봐 줘"], ["나사한통", "왜 막았는데"], ["0_o", "나도 몰라ㅋㅋ"]]}, {"id": "mzday28p03", "day": 28, "author": "부릉부릉", "time": "11:58", "text": "관문 쪽 영상 보고 갔다는 사람을 오늘 또 봄 이제 내가 아는 골목을 남들이 설명해 주는 기분임", "comments": [["지도가있어도길치", "설명 잘해 주던가"], ["부릉부릉", "아니 나한테 길 물어봄"], ["동네산책", "이게 진짜 지역 주민의 역할이지"]]}, {"id": "mzday28p04", "day": 28, "author": "초록장갑", "time": "13:21", "text": "장갑에 작은 구멍 난 거 모르고 일하다가 손가락 하나만 시원했음", "comments": [["나사한통", "이제 환기 기능도 있네"], ["초록장갑", "필요 없어"]]}, {"id": "mzday28p05", "day": 28, "author": "쉬는날엔뭐하지", "time": "15:33", "text": "쉬는 날 되면 방 정리한다는 계획 벌써 세 번째 쉬는 날로 미룸", "comments": [["관성", "다음 미루는 날은 네 번째 쉬는 날이겠네"], ["쉬는날엔뭐하지", "왜 그렇게 정확해"], ["뿌꾸", "나도 지금 침대에 누워서 정리하는 상상만 하고 있거든"]]}, {"id": "mzday28p06", "day": 28, "author": "개굴", "time": "17:09", "text": "감자튀김 먹다가 제일 긴 거 마지막에 먹으려고 남겨 뒀는데 옆 사람이 그거 먹어버림.......", "comments": [["종점에서내려요", "제일 긴 거인 줄은 어떻게 알았어"], ["개굴", "내가 재봤으니까"], ["관성", "뭘로"], ["개굴", "줄자로"], ["관성", "그건 왜 들고 다니는데"]]}] );

feedPosts.push(...[{"id": "mzday29p01", "day": 29, "author": "종이수집가", "time": "08:23", "text": "스티커 하나 예쁘게 붙이려다가 각도 맞추느라 15분 씀 손이 덜덜 떨려", "comments": [["관성", "어케 됌???"], ["종이수집가", "망했다"], ["마춤뻡검사기", "됌X 됨O"]]}, {"id": "mzday29p02", "day": 29, "author": "잠깐만요", "time": "10:17", "text": "엘리베이터 버튼 누르려고 손 뻗었는데 이미 내가 누른 층에 불 들어와 있었음 누가 눌렀지", "comments": [["나사한통", "너"], ["잠깐만요", "아니 기억이 안 나"], ["관성", "범인은 가까이에 있다"]]}, {"id": "mzday29p03", "day": 29, "author": "초록장갑", "time": "11:40", "text": "오늘은 연차썼다 ㅋㅋㅋㅋㅋㅋ와 세상이 너무 아름다운데", "comments": [["나사한통", "부럽다 이 배신자"], ["초록장갑", "깔 깔 깔"], ["나사한통", "나도 쓸래 나도 연차"]]}, {"id": "mzday29p04", "day": 29, "author": "늦잠", "time": "14:08", "text": "내일 약속 있는데 무슨 옷 입지 고민만 하다가 오늘 하루가 끝나게 생김", "comments": [["뿌꾸", "내일의 네가 고르겠지"], ["늦잠", "내일의 나도 지금 나인데"], ["개굴", "그럼 계속 고민해"]]}, {"id": "mzday29p05", "day": 29, "author": "부릉부릉", "time": "16:22", "text": "배달 갔다가 건물 앞 화분이 전부 자리를 바꿨더라 잠깐 다른 데 온 줄 알았음", "comments": [["동네산책", "화분도 이사하나 봐"], ["부릉부릉", "나보다 자주 옮기는 것 같음"]]}, {"id": "mzday29p06", "day": 29, "author": "책상위에만놓지말자", "time": "17:07", "text": "책상 정리하려고 물건 다 한쪽으로 밀었음 이제 그 한쪽이 새로운 책상이 됐다", "comments": [["종이수집가", "구역을 나누면 정리된 거 맞음"], ["관성", "그 구역 이름이 쓰레기산"], ["책상위에만놓지말자", "정정해 줄래..."]]}] );

