feedPosts.push(...[{"id": "mz30_01", "day": 30, "author": "관문골목", "time": "17:05", "text": "오늘 가게 앞에 놓인 작은 의자가 바람 때문에 한 바퀴 돌아가 있었음. 누가 앉아 있다 일어나면서 돌린 줄 알았는데 그냥 바람이었네.", "comments": [["동네산책", "회정 회오리이이이이이"], ["관문골목", "잠깐 의자 날아간다"]]}, {"id": "mz30_02", "day": 30, "author": "지도가있어도길치", "time": "16:42", "text": "오늘도 길 찾다가 지도에 없는 골목으로 들어갔는데 막상 거기가 제일 빠른 길이었음. 이쯤 되면 지도가 나한테 배워야 하는 거 아님???", "comments": [["기린린", "닉언불일치 ㅋㅋ"], ["지도가있어도길치", "잘못 들어간 길이지만 말야ㅋㅋㅋ"]]}, {"id": "mz30_03", "day": 30, "author": "도시에서락을하면도시락", "time": "14:18", "text": "다들 토마토 좋아해?", "comments": [["관성", "ㄱ그걸왜먹음???"], ["나사한통", "난 좋아함 이쁘게 생김"], ["관성", "풀냄새 진짜 싫어 그거"]]}, {"id": "mz30_04", "day": 30, "author": "종점에서내려요", "time": "19:00", "text": "퇴근길에 내릴 정류장 지나칠 뻔했는데 옆자리 분이 먼저 일어나셔서 덩달아 내림. 모르는 분께 은근히 고마운 날.", "comments": [["부릉부릉", "다행이다ㅋㅋ"], ["종점에서내려요", "오늘은 종점 전에 내렸지"]]}, {"id": "mz30_05", "day": 30, "author": "오늘은제가먼저내립니다", "time": "20:10", "text": "셋이 만나 저녁 먹기로 했는데 약속 장소 찾는 얘기만 20분째. 다 같이 같은 건물 앞에 서 있다는 게 제일 어이없다.", "comments": [["개굴", "건물 이름은 봤음?"], ["오늘은제가먼저내립니다", "다들 뒷문 앞에 있었음"]]}, {"id": "mz30_06", "day": 30, "author": "뿌꾸", "time": "21:30", "text": "종이컵에 작은 별 그려 봤는데 제법 귀여움. 이제 버리기 아까워짐.", "comments": [["초록장갑", "귀엽다"], ["뿌꾸", "맞아 그래서 책상 위에 있음"]]}, {"id": "mz30_week_01", "day": 30, "author": "동네산책", "time": "11:20", "text": "오늘 개굴이랑 오프함!! 재밌었다 그치", "comments": [["개굴", "담에도 또 만나자"], ["동네산책", "ㅋㅋㅋㅋㅋㅋ좋아"]], "weekendOnly": true}, {"id": "mz30_week_02", "day": 30, "author": "초록장갑", "time": "15:45", "text": "주말에 장갑 빨아 놓고 널다가 한 짝이 뒤집혀 있다는 걸 이제야 봄. 다시 뒤집어 널까 그냥 둘까", "comments": [["나사한통", "그냥 두면 마를 때 알아서 돌아오는 기능은 없을텐데"], ["초록장갑", "그건 아는데 귀찮아서..."]], "weekendOnly": true}, {"id": "mz30_week_03", "day": 30, "author": "프리즘수집가", "time": "18:10", "text": "같은 잔에 물을 마셔도 조명 바꾸면 색이 달라 보이는 게 신기함. 오늘은 창가에 앉아서 한참 구경했다.", "comments": [["관성", "과학 관찰 일지 같다"], ["프리즘수집가", "나중에 나도 이런 거 개발할거야"]], "weekendOnly": true}] );

